#' Convert an agricolae field book for saving to Breedbase
#'
#' Adapts a design generated by the CRAN package \pkg{agricolae} to
#' [save_breedbase()] and [phenotype_template()]. The randomization is kept;
#' no design is generated or randomized by this function. Conversion is
#' entirely offline and does not require agricolae to be installed.
#' To also record the trial name, location, breeding program and year for
#' a later save, use [prepare_breedbase_trial()].
#'
#' @param design An agricolae design (a list with `book` and `parameters`),
#'   or its field-book data frame, including the result of
#'   `agricolae::zigzag()`.
#' @param accession Name of the field-book column containing Breedbase
#'   accession names. Inferred only when exactly one non-structural column
#'   is present. For factorial, split-plot, strip-plot and Graeco-Latin
#'   designs, explicitly select the genotype column; combinations of
#'   treatment factors are not turned into accession names.
#' @param checks Character vector of check accession names. By default,
#'   uses `parameters$trt1` for an agricolae augmented block design
#'   (`design.dau()`), and no checks for other designs. Use `character(0)`
#'   to explicitly mark no checks.
#' @param design_type Breedbase design type. Inferred for `crd` (`"CRD"`),
#'   `rcbd` (`"RCBD"`), `alpha` (`"Alpha"`), `lattice` (`"Lattice"`),
#'   `dau` (`"Augmented"`), `split` (`"splitplot"`) and `strip`
#'   (`"stripplot"`); factorial designs use their underlying CRD or RCBD.
#'   Required for a bare field book or a design without a direct Breedbase
#'   type, such as Latin squares, Youden, BIB and cyclic designs. Select a
#'   compatible type accepted by your Breedbase installation; the original
#'   agricolae type remains in the returned object's `parameters`.
#' @param plot,block,rep,row,col Optional field-book column names. Defaults
#'   detect `plots`, `block`, a replicate column (`replication`, `replicate`,
#'   `rep` or `r`), and the pair `row`, `col`. Missing block or replicate
#'   columns are set to 1; in RCBD, block also supplies replicate. Augmented
#'   blocks are not treated as replicates. Coordinates are used only when
#'   both columns are available, and are never inferred from plot numbers
#'   or the sketch. Mapped numeric columns must contain positive integers.
#'
#' @details
#' Plot numbers, accessions, blocks, replicates and any explicit coordinates
#' retain their field-book values. Alpha designs' `cols` column describes
#' positions within blocks and is not assumed to be a field coordinate.
#' For split plots, where `plots` is repeated across subplots, sequential
#' unique plot numbers are assigned in field-book row order. An explicit
#' `plot` mapping must always identify each row uniquely.
#'
#' The original field book and generation parameters are retained as
#' `book` and `parameters`. Saving uploads one plot per row, with accession,
#' block, replicate, check status and optional coordinates. Other treatment
#' factors and the main-plot/subplot hierarchy are retained locally, but are
#' not uploaded by [save_breedbase()]. In particular, this conversion does
#' not create treatment records or an analysis model for factorial designs.
#'
#' Accession names must already exist in Breedbase. Supply the new trial's
#' name, year, location, description and breeding program to
#' [save_breedbase()]; use `dry_run = TRUE` to inspect or check before saving.
#'
#' @return A `breedbase_design` list with the standardized plot table
#'   (`design`), Breedbase `design_type`, original `book` and `parameters`.
#'   Pass the whole object to [save_breedbase()] or [phenotype_template()].
#' @seealso [save_breedbase()], [phenotype_template()]
#' @examples
#' if (requireNamespace("agricolae", quietly = TRUE)) {
#'   accessions <- c("G1", "G2", "G3", "CHECK_A")
#'   randomized <- agricolae::design.rcbd(accessions, r = 3, seed = 2026)
#'   converted <- as_breedbase_design(randomized, checks = "CHECK_A")
#'   payload <- save_breedbase(converted, trial_name = "RCBD_2026",
#'     year = 2026, location = "Ibadan", description = "RCBD from agricolae",
#'     dry_run = TRUE)
#'   sheet <- phenotype_template(converted, "RCBD_2026", traits = "yield")
#' }
#' @export
as_breedbase_design <- function(design, accession = NULL, checks = NULL,
                               design_type = NULL, plot = NULL, block = NULL,
                               rep = NULL, row = NULL, col = NULL) {
  parameters <- if (is.list(design) && !is.data.frame(design)) design$parameters else NULL
  book <- if (is.data.frame(design)) design else if (is.list(design)) design$book else NULL
  if (!is.data.frame(book) || nrow(book) == 0L) {
    stop("`design` must be an agricolae design with a non-empty `book`, or a field-book data frame.",
         call. = FALSE)
  }
  if (anyNA(names(book)) || any(!nzchar(names(book))) || anyDuplicated(names(book))) {
    stop("Field-book column names must be non-empty and unique.", call. = FALSE)
  }
  if (!is.null(parameters) && !is.list(parameters)) {
    stop("`parameters` must be a list, as returned by agricolae.", call. = FALSE)
  }
  source_type <- if (is.list(parameters)) parameters$design else NULL
  if (!is.null(source_type) && (length(source_type) != 1L || is.na(source_type))) {
    stop("`parameters$design` must contain one design type.", call. = FALSE)
  }
  if (is.null(design_type)) {
    types <- c(crd = "CRD", rcbd = "RCBD", alpha = "Alpha", lattice = "Lattice",
               dau = "Augmented", split = "splitplot", strip = "stripplot")
    mapped_type <- if (identical(source_type, "factorial")) parameters$applied else source_type
    design_type <- unname(types[mapped_type])[1L]
  }
  if (length(design_type) != 1L || is.na(design_type) || !nzchar(design_type)) {
    stop("Give `design_type`: this field book has no automatic Breedbase design type",
         if (!is.null(source_type)) paste0(" ('", source_type, "')"),
         ". Accepted types: ", paste(bb_design_types(), collapse = ", "), ".", call. = FALSE)
  }
  if (!design_type %in% bb_design_types()) {
    stop("`design_type` must be one of the types Breedbase accepts: ",
         paste(bb_design_types(), collapse = ", "), ".", call. = FALSE)
  }

  column <- function(value, candidates, argument) {
    if (is.null(value)) return(intersect(candidates, names(book))[1L])
    if (!is.character(value) || length(value) != 1L || is.na(value) || !value %in% names(book)) {
      stop("`", argument, "` must name one column of the field book.", call. = FALSE)
    }
    value
  }
  plot_col <- column(plot, "plots", "plot")
  block_col <- column(block, "block", "block")
  rep_col <- column(rep, c("replication", "replicate", "rep", "r"), "rep")
  row_col <- column(row, "row", "row")
  col_col <- column(col, "col", "col")
  if (is.na(plot_col)) stop("Give `plot`, the column containing plot numbers.", call. = FALSE)
  if (xor(is.na(row_col), is.na(col_col))) {
    stop("Give both `row` and `col` columns, or omit both coordinates from the field book.", call. = FALSE)
  }
  if (is.null(accession)) {
    structural <- c("plots", "splots", "block", "replication", "replicate", "rep", "r",
                    "row", "col", "cols", "group", plot_col, block_col, rep_col, row_col, col_col)
    candidates <- setdiff(names(book), structural)
    if (length(candidates) != 1L) {
      stop("Give `accession`, the column containing Breedbase accession names; found ",
           length(candidates), " possible columns: ", paste(candidates, collapse = ", "), ".",
           call. = FALSE)
    }
    accession <- candidates
  }
  accession <- column(accession, character(0), "accession")
  entries <- as.character(book[[accession]])
  if (anyNA(entries) || any(!nzchar(trimws(entries)))) {
    stop("The accession column contains missing or empty names.", call. = FALSE)
  }
  integer_column <- function(name, argument, default = 1L) {
    if (is.na(name)) return(base::rep(default, nrow(book)))
    values <- suppressWarnings(as.numeric(as.character(book[[name]])))
    if (any(!is.finite(values) | values < 1 | values > .Machine$integer.max | values != floor(values))) {
      stop("The `", argument, "` column must contain positive integers without missing values.", call. = FALSE)
    }
    as.integer(values)
  }
  plots <- integer_column(plot_col, "plot")
  if (anyDuplicated(plots)) {
    if (is.null(plot) && identical(design_type, "splitplot") && "splots" %in% names(book) &&
        !anyDuplicated(book[c(plot_col, "splots")])) {
      plots <- seq_len(nrow(book))
      message("Split-plot field book: assigning unique plot numbers in row order; original plots and splots are in `book`.")
    } else {
      stop("Plot numbers must be unique for each field-book row; give `plot` with unique numbers.", call. = FALSE)
    }
  }
  blocks <- integer_column(block_col, "block")
  if (is.na(rep_col) && (identical(source_type, "rcbd") ||
      (source_type %in% c("split", "factorial") && identical(parameters$applied, "rcbd")) ||
      identical(source_type, "strip") || (is.null(source_type) && identical(design_type, "RCBD")))) {
    reps <- blocks
  } else {
    reps <- integer_column(rep_col, "rep")
  }
  if (is.null(checks)) checks <- if (identical(source_type, "dau")) parameters$trt1 else character(0)
  checks <- as.character(checks)
  if (anyNA(checks) || any(!nzchar(trimws(checks)))) stop("`checks` contains missing or empty names.", call. = FALSE)
  absent <- setdiff(checks, entries)
  if (length(absent)) stop("Check accession(s) absent from the field book: ", paste(absent, collapse = ", "), ".",
                           call. = FALSE)
  d <- tibble::tibble(plots = plots, all_entries = entries, block = blocks, rep = reps,
                      is_control = as.integer(entries %in% checks))
  if (!is.na(row_col)) {
    d$row <- integer_column(row_col, "row")
    d$col <- integer_column(col_col, "col")
    if (anyDuplicated(d[c("row", "col")])) {
      stop("Field coordinates must identify a unique position for each plot; use global field coordinates.",
           call. = FALSE)
    }
  }
  structure(list(design = d, design_type = design_type, book = book, parameters = parameters),
            class = "breedbase_design")
}

# Design types accepted by the Breedbase study upload.
bb_design_types <- function() {
  c("CRD", "Alpha", "MAD", "Lattice", "Augmented", "RCBD", "p-rep", "splitplot",
    "stripplot", "greenhouse", "Westcott")
}
